save("local", "7-law.html", page("local", 7, "관련법",
    title="가게 홈페이지 표시 의무와 처리방침 만드는 방법 (동네 매장 코스 7단계)",
    desc="광고를 켜기 전에 홈페이지 첫 화면의 표시 사항 여섯 가지와 개인정보 처리방침을 확인하는 순서예요. 홈페이지나 예약 페이지가 없는 가게는 건너뛰어도 됩니다.",
    lead="홈페이지나 예약 페이지가 있으면 첫 화면 표시 사항과 처리방침 두 가지를 확인합니다. 없으면 이 단계는 건너뛰고 8단계로 가세요.",
    prep="사업자등록증, 홈페이지 관리 화면 로그인", minutes="30분", cost="무료",
    do=[
        ("홈페이지 첫 화면 맨 아래를 열어 여섯 가지가 있는지 세어 보세요.", " 상호와 대표자 이름, 영업소 주소, 전화번호와 이메일, 사업자등록번호, 이용약관, 그리고 시행령이 정한 사항입니다. 홈페이지에서 예약이나 결제를 받으면 이 여섯 가지를 적어야 해요."),
        ("없는 항목을 홈페이지 관리 화면의 「푸터」나 「하단 정보」에 넣으세요.", " 빌더(아임웹·카페24 등)는 설정 메뉴에 「사업자 정보」 칸이 따로 있어요."),
        ("예약 폼이나 문의 폼이 있는지 확인하세요.", " 손님 이름과 전화번호를 받는 칸이 하나라도 있으면 개인정보 처리방침이 필요합니다. 네이버 예약이나 카카오 채널로만 받으면 그 플랫폼의 방침이 적용돼요."),
        ("처리방침을 만드세요.", " 개인정보 포털(privacy.go.kr)의 「개인정보 처리방침 작성지원」에서 항목을 고르면 문서가 만들어집니다. 무엇을 받는지, 왜 받는지, 언제까지 갖고 있는지, 책임자(사장님)와 연락처를 적습니다."),
        ("처리방침을 홈페이지에 링크로 걸어 두세요.", " 첫 화면 아래와 폼이 있는 페이지에 「개인정보 처리방침」 링크를 넣습니다. 가게 안에 붙여 두는 것으로는 대신이 안 돼요."),
        ("폼이 있는 페이지 주소가 https로 시작하는지 보세요.", " http면 호스팅이나 빌더 설정에서 보안 인증서를 켭니다."),
        ("택배로도 팔기 시작했다면 통신판매업 신고를 확인하세요.", " 매장에서만 결제하면 해당이 없어요. 온라인 판매 코스 3단계에 신고 절차가 있습니다."),
    ],
    done=["첫 화면 아래에 여섯 가지가 다 있다", "폼이 있으면 처리방침 링크가 걸려 있다", "폼 페이지가 https로 열린다"],
    blocked=[
        ("홈페이지가 아예 없어요", "이 단계는 건너뛰고 8단계로 가세요. 플레이스에 상호·주소·전화를 사실대로 적은 것으로 충분합니다."),
        ("신고번호를 첫 화면에 넣어야 한다던데요", "통신판매업 신고번호는 첫 화면 여섯 가지에 없고 광고에 적는 항목이에요. 온라인으로 팔 때만 해당합니다."),
        ("미용실인데 플레이스에 가격을 어떻게 적나요", "가게 안에 붙인 「최종지불요금표」(부가세·재료비 포함 값)와 같은 값을 적으세요. 공중위생관리법 시행규칙 별표 4가 미용업자에게 요금표 게시를 정하고 66㎡ 이상이면 바깥에도 붙이라고 해요. 점빼기·문신 같은 의료행위 표현은 광고에 못 씁니다. 학원이면 등록번호·명칭·교습과정·교습비를 광고에 적어야 하고요."),
        ("술집인데 「맥주 1+1」 게시물을 올려도 되나요", "국민건강증진법 제8조의2가 주류 광고에 「품명·종류·특징을 알리는 것 외에 판매촉진을 위하여 경품 및 금품을 제공한다는 내용」을 넣지 말라고 해요. 1+1이나 「술 시키면 안주 서비스」가 여기 걸릴 수 있어요. 음주를 권하거나 미성년자·임산부가 마시는 장면, 운전·작업 중 음주 묘사도 금지이고 광고에는 경고문구가 있어야 해요. 「오늘 생맥주 있어요」처럼 품명과 값만 적으세요."),
        ("음식점인데 글에 「면역력에 좋다」「다이어트 효과」를 써도 되나요", "안 돼요. 식품 등의 표시·광고에 관한 법률 제8조가 질병 예방·치료 효능이 있는 것처럼 보이는 광고, 의약품이나 건강기능식품으로 오인할 광고, 거짓·과장, 다른 가게 비방, 근거 없는 비교를 금지해요. 블로그·인스타그램·플레이스 소식 글도 광고예요. 재료·조리법·맛처럼 사실만 적으세요."),
    ],
    why='<a href="/guide/before-selling.html">온라인으로 팔기 전에 법이 요구하는 것</a>',
    nxt='  <a href="/local/8-powerlink.html">다음 단계. 파워링크</a>\n  <a href="/guide/before-selling.html">설명. 온라인으로 팔기 전에 법이 요구하는 것</a>',
    sources=[A("https://www.law.go.kr/LSW/lsInfoP.do?lsiSeq=269957", "식품 등의 표시ㆍ광고에 관한 법률 제8조", "2026-09-18"), A("https://www.law.go.kr/LSW/lsInfoP.do?lsiSeq=285763", "국민건강증진법 제8조의2 주류광고의 제한", "2026-09-18"), A("https://law.go.kr/LSW/flDownload.do?gubun=&flSeq=75924629&bylClsCd=110201", "공중위생관리법 시행규칙 [별표 4] 미용업자 준수사항", "2026-09-18"), A("https://www.law.go.kr/LSW/lsInfoP.do?lsiSeq=284907", "학원법 시행령 제16조의3 광고 표시 사항", "2026-09-18"), SITE + ' <a href="/guide/before-selling.html">온라인으로 팔기 전에 법이 요구하는 것</a>(전자상거래법 제10조, 개인정보 보호법 제30조와 시행령 제31조 원문은 그 글에)', '<span class="grade">B</span> 개인정보 포털(privacy.go.kr) 처리방침 작성지원(화면을 직접 확인하지는 못했어요)'],
    order=7))

