save("local", "8-powerlink.html", page("local", 8, "파워링크",
    title="네이버 파워링크 광고 직접 시작하는 방법 (동네 매장 코스 8단계)",
    desc="네이버 광고주센터에서 파워링크를 켜는 순서예요. 가입, 비즈머니 충전, 캠페인(하루예산), 광고그룹(연결 주소·기본 입찰가·매체), 키워드와 소재 등록, 검토까지 네이버 도움말 순서 그대로입니다.",
    lead="처음으로 돈이 드는 단계예요. 검색어 하나, 하루예산 하나로 한 주만 켜 보고 9단계 기록으로 판단합니다. 2~6단계가 안 돼 있으면 여기서 멈추고 돌아가세요.",
    prep="사업자등록증, 광고를 눌렀을 때 보여 줄 페이지 주소(플레이스나 블로그 글), 결제 카드, 한 달 광고 예산(예산을 30으로 나눈 값이 하루예산)", minutes="1시간", cost="돈 듦 (클릭될 때마다)", result="광고 검토 영업일 1~2일 (비즈머니 잔액이 있어야 시작)",
    do=[
        ("네이버 광고주센터(ads.naver.com)에 사장님 이름으로 가입하세요.", " 대행사가 대신 만들어 준 계정은 쓰지 않습니다. 과금 내역을 사장님이 직접 봐야 해요. 가입 뒤 화면에 「첫 광고비 지원」 안내가 뜨면 신청하세요. 가입일부터 60일 동안 쓴 광고비를 최대 50만 원까지 비즈쿠폰으로 돌려주는 프로그램인데 직접 신청해야 받습니다(2026년 5월 7일 기준)."),
        ("비즈머니를 충전하세요.", " 신용카드는 100원부터, 네이버페이 계좌 간편결제는 1만 원부터 됩니다. 최초 1회 실명 인증을 거쳐요. 잔액이 있어야 광고 검토가 시작됩니다."),
        ("「검색광고 > 광고 관리」에서 캠페인을 만드세요.", " 캠페인 유형은 「파워링크」, 이름은 알아볼 수 있게, 하루예산은 한 달 예산을 30으로 나눈 금액을 넣습니다. 「예산을 하루 동안 균등하게 배분」을 켜면 아침에 다 소진되는 걸 막아요. 「저장하고 계속하기」를 누릅니다."),
        ("광고그룹을 만드세요.", " URL에는 광고를 눌렀을 때 갈 페이지 주소를 넣습니다. 사이트 이름은 광고에 보이니 가게 이름으로요. 기본 입찰가는 낮게 시작하고 광고그룹 하루예산도 넣습니다."),
        ("광고그룹의 「고급 옵션」에서 매체를 확인하세요.", " 파워링크는 네이버 밖 제휴 사이트에도 나갑니다. 네이버 검색에서만 보이게 하려면 다른 매체를 끄세요. PC·모바일 입찰가 가중치도 여기서 정합니다."),
        ("키워드를 직접 입력하세요.", " 「동네 이름 + 업종」 하나로 시작합니다. 한 줄에 하나씩 넣고 연관 키워드 추천은 처음엔 무시해도 돼요. 동네 검색어는 광고 칸이 3개뿐일 수 있으니 여러 개 넣기보다 하나를 제대로 봅니다."),
        ("소재(광고 문구)를 쓰세요.", " 제목에는 가게 이름과 손님이 찾는 것, 설명에는 영업시간·주차·위치처럼 손님이 전화로 묻는 답을 넣습니다. 「최고」 「1등」 같은 말은 빼세요."),
        ("저장하고 검토를 기다리세요.", " 비즈머니 잔액이 있어야 검토가 진행되고 영업일 1~2일 걸립니다."),
        ("켜기 전에 9단계 기록의 첫 주 줄부터 적으세요.", " 켜기 전 숫자가 있어야 켠 뒤와 비교할 수 있어요. 한 주만 켜고 클릭 수와 전화 수를 적습니다."),
    ],
    done=["광고 계정이 사장님 이름이고 과금 내역을 직접 볼 수 있다", "캠페인 하루예산과 광고그룹 매체 설정을 확인했다", "키워드 하나, 소재 하나가 검토 중이거나 켜져 있다", "켜기 전 주의 전화 수·정산액을 적어 두었다"],
    blocked=[
        ("광고가 승인이 안 나요", "소재나 연결 페이지가 심사 기준에 걸린 거예요. 광고주센터의 검토 결과 메시지를 보고 그 부분만 고쳐 다시 저장합니다. 병원 등 사전 심의 업종은 사이트 이름이 노출되지 않아요."),
        ("돈은 나가는데 전화가 없어요", "광고가 아니라 눌러서 가는 페이지 문제예요. 2·3단계 플레이스 정보부터 다시 채우세요. 하루예산을 넘겨 과금될 수 있으니 매체 설정도 확인합니다."),
        ("「월정액에 상위 노출 보장」 전화가 와요", "네이버 광고는 실시간 입찰이고 클릭될 때만 과금돼요. 월정액 결제 유도는 네이버가 사칭 피해 사례로 안내하는 것입니다."),
        ("파워링크 말고 플레이스광고는 어떻게 켜나요", "같은 광고주센터에서 캠페인 유형을 「플레이스 유형」으로 만들고, 광고그룹 유형에서 플레이스광고나 지역소상공인광고를 고른 뒤 스마트플레이스 아이디로 인증하면 업체 정보가 그대로 광고가 돼요. 플레이스광고는 클릭당 과금에 최저 입찰가 50원이고 노출은 무료, 지역소상공인광고는 보인 횟수마다 0.5원이에요."),
        ("경쟁 가게가 우리 광고를 계속 누르는 것 같아요", "구매 뜻 없이 반복해서 누르는 건 네이버가 무효클릭으로 걸러 과금에서 빼요. 필터링 결과와 IP 기록은 공개하지 않습니다. 키워드·광고·사이트를 점검한 뒤에도 의심되면 광고주센터 클린센터에서 클릭 로그와 함께 「무효클릭 문의」로 조사를 의뢰하세요. 반대로 사장님이 경쟁 광고를 모니터링 삼아 누르는 것도 무효클릭이 되어 광고 이용이 제한될 수 있어요."),
        ("플레이스광고를 켰는데 검색해도 안 보여요", "플레이스광고는 같은 검색어에 여러 업체가 참여하면 랜덤으로 나가서 사장님 화면에는 다른 업체만 보일 수 있다고 도움말에 적혀 있어요. 실시간 노출 여부는 확인이 어렵고 광고주센터 보고서의 노출수·클릭수나 스마트플레이스 통계로 봐요. 검토 통과나 설정 변경 뒤 반영은 최대 3시간이고 광고그룹의 제외검색어와 지역·매체·성별·연령 전략이 걸려 있으면 안 나옵니다."),
        ("플레이스광고는 키워드를 고를 수 있나요", "따로 키워드를 넣지 않아요. 등록된 업체 정보로 연관 키워드를 자동으로 맞춰 나가고 등록할 때 노출 예상 키워드를 보여 줘요. 원치 않는 키워드는 실제 노출된 뒤 「제외검색어」로 뺍니다. 모바일 통합검색에는 목록 위·중간에 최대 6개, PC 는 쪽마다 2~4개씩 최대 12개가 나간다고 적혀 있어요."),
        ("지역소상공인광고는 어디에 보이나요", "네이버 PC 첫 화면 오른쪽 아래, 뉴스·블로그, 모바일 우리동네판 같은 콘텐츠 자리에 나가요. 사장님이 고른 읍·면·동에 있는 이용자에게 보이지만 이용자의 관심 지역 기준이라 안 고른 지역에도 나갈 수 있다고 적혀 있어요. 끄려면 광고주센터에서 캠페인 ON/OFF 로 중지합니다."),
    ],
    why='<a href="/guide/powerlink.html">파워링크, 문서에 적힌 대로만</a>과 <a href="/guide/ads.html">광고비는 어디서 새나</a>',
    nxt='  <a href="/local/9-record.html">다음 단계. 12주 기록</a>\n  <a href="/guide/powerlink.html">설명. 파워링크, 문서에 적힌 대로만</a>',
    sources=[A(ADS + "1045", "네이버 광고주센터 「플레이스광고가 노출되지 않아요」", "2026-09-19"), A(ADS + "401", "「플레이스광고가 노출될 키워드를 선택할 수 있나요」", "2026-09-19"), A(ADS + "394", "「플레이스광고 검색 지면 노출 영역 및 개수」", "2026-09-19"), A(ADS + "1046", "「지역소상공인광고 노출영역과 노출방식」", "2026-09-19"), A(ADS + "1284", "「지역소상공인 광고 노출은 어떻게 중지하나요」", "2026-09-19"), A(ADS + "1480", "네이버 광고주센터 「파워링크 광고 등록 방법이 궁금해요」"), A("https://ads.naver.com/help/cleancenter", "「클린센터(무효클릭)」", "2026-09-17"), A("https://ads.naver.com/notice/30385", "「광고주 성장 프로그램 > 첫 광고비 지원 변경 안내」", "2026-09-17"), A(ADS + "1175", "「캠페인 하루예산과 예산 배분」"), A(ADS + "1170", "「비즈머니는 어떻게 충전하나요?」"), A(ADS + "1012", "「내 파워링크 광고가 어디에 노출되는지 궁금해요」"), A("https://ads.naver.com/help/faq/1044", "「플레이스광고가 무엇인지 궁금해요」", "2026-09-18"), A("https://ads.naver.com/help/faq/1326", "「지역소상공인광고는 어떻게 등록하나요」", "2026-09-18")],
    order=8))

