save("local", "9-record.html", page("local", 9, "12주 기록",
    title="마케팅 효과 12주 기록하는 방법 (동네 매장 코스 9단계)",
    desc="매주 같은 요일 5분씩 숫자를 적는 표를 만드는 순서예요. 한 주에 한 가지만 바꾸고 전화 수·리뷰 수·정산액처럼 가게에 실제로 들어온 숫자만 적습니다. 12주 뒤 첫 줄과 마지막 줄을 비교합니다.",
    lead="앞에서 한 일이 효과가 있었는지 알아내는 틀이에요. 새로 하는 일은 없고 매주 5분씩 적기만 하면 됩니다.",
    prep="종이 공책이나 휴대폰 메모, 달력", minutes="매주 5분", cost="무료",
    do=[
        ("달력에 매주 같은 요일 5분을 잡으세요.", " 월요일 아침처럼 빠뜨리기 어려운 때로요."),
        ("표를 만드세요.", " 가로줄은 주차(1~12주), 세로칸은 「바꾼 것 / 광고비 / 전화 수 / 새 리뷰 수 / 답글 단 수 / 정산액(실제 들어온 돈) / 비고」 일곱 개입니다. 만들어 둔 <a href=\"/guide/record-sheet.html\">빈 표</a>를 인쇄하거나 CSV로 내려받아도 돼요."),
        ("첫 주는 아무것도 바꾸지 말고 「바꾼 것 없음」으로 적으세요.", " 이 줄이 나중에 비교 기준이 됩니다."),
        ("전화 수는 스마트콜 통계(없으면 가게 전화기 기록)로, 리뷰 수는 리뷰 탭 집계로, 정산액은 통장 입금액으로 적으세요.", " 노출 수·클릭 수·순위는 적지 않습니다. 플랫폼이 세는 숫자라 매일 흔들려요."),
        ("한 주에 한 가지만 바꾸세요.", " 사진을 올린 주에는 광고를 켜지 않고 광고를 켠 주에는 가격을 바꾸지 않습니다. 둘을 같이 바꾸면 어느 쪽 덕인지 알 수 없어요."),
        ("모르는 값은 빈칸으로 두세요.", " 0과 모름은 다릅니다. 안 센 칸에 0을 넣지 마세요."),
        ("12주 뒤 첫 줄과 마지막 줄을 나란히 놓고 전화 수와 정산액이 늘어난 주에 바꾼 일이 무엇이었는지 보세요.", " 효과 있던 일은 계속하고 없던 일은 줄인 뒤, 2단계로 돌아가 다음 12주를 시작합니다."),
    ],
    done=["달력에 요일이 잡혀 있다", "표 첫 줄이 「바꾼 것 없음」으로 채워져 있다"],
    blocked=[
        ("전화 수를 어떻게 세요?", "가장 정확한 건 네이버 「스마트콜」이에요. 스마트플레이스에 등록된 가게면 무료로 050 가상번호가 나오고 손님이 전화한 날짜·횟수·안 받은 건수까지 기록돼요. 스마트플레이스 > 내 업체 > 정보수정 > 전화번호 > 「우리가게 전화 대신 받아주기(스마트콜)」에서 켭니다. 대표번호가 1xxx·080·다른 050이면 안 되고, 통계는 최근 1년치만 보여요. 스마트콜을 안 쓰면 가게 전화기 수신 기록으로 12주 내내 같은 것을 셉니다."),
        ("주문이 많아 정산액 계산이 힘들어요", "통장에 실제로 찍힌 입금액 합계만 적으세요. 결제 금액이 아니라 수수료를 뺀 돈이에요."),
        ("플레이스 조회 수는 어디서 보나요", "스마트플레이스 통계 탭이에요. 주인 권한 아이디로 들어가면 플레이스 페이지 유입 수, 성별·연령, 시간·요일별 조회, 유입 채널과 검색 키워드를 볼 수 있고 데이터는 최근 1년치예요. 리포트 탭은 조회 수·예약 신청 수·리뷰 수·스마트콜 통화 수를 카드로 요약해 주는데 예약·주문과 스마트콜을 안 쓰면 요약 카드가 안 나와요."),
        ("검색 결과에 우리 전화가 0507로 나와요", "스마트콜을 켜면 나오는 가상 전화번호예요. 원래 모바일에서만 050으로 보이던 것을 PC 검색 결과에도 보이게 바꿨다고 도움말에 있어요. 손님이 걸면 「네이버에서 연결 드립니다」 안내 뒤 가게 전화로 이어지고 대표번호 자체를 스마트콜로 바꿀 수는 없어요."),
    ],
    why='<a href="/guide/record.html">12주 기록, 판단은 정산액으로</a>',
    nxt='  <a href="/p/local/">동네 매장 코스 처음으로</a>\n  <a href="/guide/record.html">설명. 12주 기록, 판단은 정산액으로</a>',
    sources=[A(H + "20527", "「플레이스 통계 안내」", "2026-09-19"), A(H + "20524", "「플레이스 리포트 안내」", "2026-09-19"), A(H + "20382", "「050번호로 노출되는 업체 전화번호 수정 방법」", "2026-09-19"), A(H + "20480", "네이버 스마트플레이스 사업주 고객센터 「스마트콜 신청 방법」", "2026-09-18"), A(H + "20472", "「스마트콜을 발급받기 위한 조건 안내」", "2026-09-18"), A(H + "20520", "「사업주 플레이스 통계 안내」", "2026-09-18"), SITE + ' <a href="/guide/record.html">12주 기록, 판단은 정산액으로</a>(12주와 기록 칸은 저희가 정한 틀이에요)'],
    order=9))
